<?php
require_once __DIR__.'/_init.php'; require_once __DIR__.'/../includes/admin-ui.php'; $pdo=db();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['id']??0);$status=$_POST['status']??'baru';if(!in_array($status,['baru','ditinjau','selesai'],true))$status='baru';$pdo->prepare('UPDATE laporan_aktivitas SET status=? WHERE id=?')->execute([$status,$id]);flash('success','Status laporan diperbarui.');header('Location: laporan.php');exit;}
$rows=$pdo->query('SELECT * FROM laporan_aktivitas ORDER BY waktu DESC')->fetchAll();admin_header('Laporan Aktivitas','laporan'); ?>
<section class="panel"><div class="panel-head"><div><h2>Arsip laporan aktivitas</h2><p class="panel-subtitle">Tinjau laporan yang masuk dan perbarui status penanganannya.</p></div></div><?php if(!$rows): ?><div class="empty">Belum ada laporan aktivitas di database.</div><?php else: ?><div class="table-wrap"><table><thead><tr><th>Waktu</th><th>Judul</th><th>Deskripsi</th><th>Regu</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= e($r['waktu']) ?></td><td><?= e($r['judul_aktivitas']) ?></td><td><?= e(mb_strimwidth($r['deskripsi'],0,100,'…')) ?></td><td><?= e($r['regu']??'-') ?></td><td><span class="pill <?= $r['status']==='selesai'?'green':($r['status']==='ditinjau'?'orange':'') ?>"><?= e(ucfirst($r['status'])) ?></span></td><td><form method="post" class="table-actions"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="id" value="<?= (int)$r['id'] ?>"><select name="status"><option value="baru" <?= $r['status']==='baru'?'selected':'' ?>>Baru</option><option value="ditinjau" <?= $r['status']==='ditinjau'?'selected':'' ?>>Ditinjau</option><option value="selesai" <?= $r['status']==='selesai'?'selected':'' ?>>Selesai</option></select><button class="btn btn-sm">Update</button></form></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section><?php admin_footer(); ?>